namespace fs = std::filesystem;

// Regular expression for filename matching, compiled once
const std::regex FILENAME_PATTERN("^(.*?)-(\\d+)-(\\d+)\\.json$");

// Mutex for thread-safe console output
std::mutex console_mutex;

// Thread-safe logger class
class FileLogger {
private:
    std::mutex log_mutex;
    std::string log_file_path;

public:
    FileLogger(const std::string& path) : log_file_path(path) {
        // Create or clear the log file
        std::ofstream log_file(log_file_path, std::ios::out | std::ios::trunc);
        if (log_file.is_open()) {
            log_file << "Timestamp,Filename,ProcessingTimeMs,StartTimestamp,EndTimestamp" << std::endl;
            log_file.close();
        }
    }

    void log_file_processing(const std::string& filename, long long processing_time_ms, 
                           const std::chrono::system_clock::time_point& start_time,
                           const std::chrono::system_clock::time_point& end_time) {
        std::lock_guard<std::mutex> lock(log_mutex);
        
        // Get current time for timestamp
        auto now = std::chrono::system_clock::now();
        auto now_time_t = std::chrono::system_clock::to_time_t(now);
        std::stringstream timestamp;
        timestamp << std::put_time(std::localtime(&now_time_t), "%Y-%m-%d %H:%M:%S");
        
        // Open file in append mode
        std::ofstream log_file(log_file_path, std::ios::app);
        if (log_file.is_open()) {
            // Convert start/end times to timestamps
            auto start_time_t = std::chrono::system_clock::to_time_t(start_time);
            auto end_time_t = std::chrono::system_clock::to_time_t(end_time);
            
            std::stringstream start_timestamp, end_timestamp;
            start_timestamp << std::put_time(std::localtime(&start_time_t), "%Y-%m-%d %H:%M:%S");
            end_timestamp << std::put_time(std::localtime(&end_time_t), "%Y-%m-%d %H:%M:%S");
            
            log_file << timestamp.str() << "," 
                     << filename << "," 
                     << processing_time_ms << ","
                     << start_timestamp.str() << ","
                     << end_timestamp.str() << std::endl;
            log_file.close();
        }
    }
};

// Global shared logger
std::shared_ptr<FileLogger> g_logger;

// Global progress tracking
std::atomic<int> files_processed{0};
std::atomic<int> db_records_updated{0};
int total_files = 0;

// Thread-safe console output
template<typename... Args>
void safe_print(const char* format, Args... args) {
    std::lock_guard<std::mutex> lock(console_mutex);
    printf(format, args...);
    fflush(stdout);
}

// Update progress bar
void update_progress() {
    int processed = files_processed.load();
    if (total_files > 0) {
        int percent = static_cast<int>(100.0 * processed / total_files);
        std::lock_guard<std::mutex> lock(console_mutex);
        printf("\rProgress: [");
        int pos = 50 * processed / total_files;
        for (int i = 0; i < 50; ++i) {
            if (i < pos) printf("=");
            else if (i == pos) printf(">");
            else printf(" ");
        }
        printf("] %d%% (%d/%d)", percent, processed, total_files);
        fflush(stdout);
    }
}

using BookLevel = std::array<std::string, 4>;

struct DataItem {
    std::vector<BookLevel> asks;
    std::vector<BookLevel> bids;
    std::string ts;
    int64_t checksum;
    int64_t prevSeqId;
    int64_t seqId;
};

struct Arg {
    std::string channel;
    std::optional<std::string> instId;
    std::optional<std::string> instType;
    std::optional<std::string> InstFamily;
    std::optional<std::string> uly;
};

struct BookData {
    Arg arg;
    std::array<DataItem, 1> data;
    std::string action;
};

struct Extend {
    bool sorted;
    bool true_elapsedTime;
};

struct JsonData {
    std::array<int64_t, 2> elapsedTime;
    std::vector<BookData> data;
    std::optional<Extend> extend;
};

// Database connection parameters
struct DbParams {
    std::string host;
    std::string user;
    std::string password;
    std::string database;
    std::string table;
    int port = 33060;
};

// Result of file analysis
struct FileAnalysisResult {
    std::string file_path;
    std::string original_file_name;
    std::string file_prefix;
    int64_t min_ts;
    int64_t max_ts;
    JsonData updated_data;
};

// Generate a temporary file name
std::string generate_temp_filename(const std::string& dir) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> dis(0, 999999);
    
    return (fs::path(dir) / fs::path(std::to_string(dis(gen)) + ".tmpjson")).string();
}

// Analyze a JSON file
std::optional<FileAnalysisResult> analyze_file(const std::string& file_path, bool sort_data) {
    try {
        std::string original_file_name = fs::path(file_path).filename().string();
        std::smatch match;
        
        if (!std::regex_match(original_file_name, match, FILENAME_PATTERN)) {
            safe_print("Warning: Skipping file with invalid name format: %s\n", original_file_name.c_str());
            return std::nullopt;
        }
        
        std::string file_prefix = match[1].str();
                
        // Parse JSON
        JsonData root;
        auto ec = glz::read_file_json(root, file_path, std::string{});
        if (ec) {
            safe_print("Error reading JSON: %d - %s\n", static_cast<int>(ec.ec), glz::format_error(ec).c_str());
            return std::nullopt;
        }
        
        if (root.data.empty()) {
            safe_print("Warning: Skipping file with missing or empty 'data' list: %s\n", 
                original_file_name.c_str());
            return std::nullopt;
        }
        
        // Extract and validate timestamps
        std::vector<int64_t> ts_list_int;
        std::vector<BookData> valid_data_items;
        
        for (size_t i = 0; i < root.data.size(); ++i) {
            try {
                const auto& entry = root.data[i];
                if (!entry.data.empty() && !entry.data[0].ts.empty()) {
                    const auto& ts_str = entry.data[0].ts;
                    
                    // Check if string contains only digits
                    bool is_digit = !ts_str.empty() && 
                                    std::all_of(ts_str.begin(), ts_str.end(), ::isdigit);
                    
                    if (is_digit) {
                        int64_t ts_int = std::stoll(ts_str);
                        ts_list_int.push_back(ts_int);
                        valid_data_items.push_back(entry);
                    } else {
                        safe_print("Warning: Invalid 'ts' format in item %zu within %s\n", 
                            i, original_file_name.c_str());
                    }
                } else {
                    safe_print("Warning: Invalid structure in item %zu within %s\n", 
                        i, original_file_name.c_str());
                }
            } catch (const std::exception& e) {
                safe_print("Warning: Error in item %zu within %s: %s\n", 
                    i, original_file_name.c_str(), e.what());
            }
        }
        
        if (ts_list_int.empty()) {
            safe_print("Warning: No valid 'ts' values found in %s\n", original_file_name.c_str());
            return std::nullopt;
        }
        
        // Find min and max timestamps
        int64_t min_ts = *std::min_element(ts_list_int.begin(), ts_list_int.end());
        int64_t max_ts = *std::max_element(ts_list_int.begin(), ts_list_int.end());
        
        // Sort data if requested
        if (sort_data && !root.data.empty()) {
            std::sort(root.data.begin(), root.data.end(), 
                [](const BookData& a, const BookData& b) {
                    if (a.data.empty() || b.data.empty()) return false;
                    return std::stoll(a.data[0].ts) < std::stoll(b.data[0].ts);
                });
        }
        
        // Update elapsedTime and extend fields
        root.elapsedTime = {min_ts, max_ts};
        if (!root.extend) {
            root.extend = Extend{}; // Initialize if not present
        }
        root.extend->true_elapsedTime = true; // Use -> to access members
        root.extend->sorted = sort_data && !root.data.empty();
        
        FileAnalysisResult result;
        result.file_path = file_path;
        result.original_file_name = original_file_name;
        result.file_prefix = file_prefix;
        result.min_ts = min_ts;
        result.max_ts = max_ts;
        result.updated_data = std::move(root);
        
        return result;
        
    } catch (const std::exception& e) {
        safe_print("Error analyzing %s: %s\n", file_path.c_str(), e.what());
        return std::nullopt;
    }
}

// Update a file with new content and rename it
bool update_file(const FileAnalysisResult& result) {
    try {
        std::string temp_dir = fs::path(result.file_path).parent_path().string();
        std::string tmp_file_path = generate_temp_filename(temp_dir);
        
        // Write to temporary file
        {
            std::string json_str;
            auto write_result = glz::write_json(result.updated_data, json_str);
            if (write_result.ec != glz::error_code::none) {
                safe_print("Error serializing JSON for %s: Error code %d\n", 
                    result.file_path.c_str(), static_cast<int>(write_result.ec));
                return false;
            }
            
            std::ofstream tmp_file(tmp_file_path, std::ios::binary);
            if (!tmp_file.is_open()) {
                safe_print("Error creating temporary file %s\n", tmp_file_path.c_str());
                return false;
            }
            
            tmp_file.write(json_str.c_str(), json_str.length());
            tmp_file.close();
        }
        
        // Create new filename
        std::string new_file_name = result.file_prefix + "-" + 
                                std::to_string(result.min_ts) + "-" + 
                                std::to_string(result.max_ts) + ".json";
        std::string new_file_path = (fs::path(temp_dir) / fs::path(new_file_name)).string();
        
        // Rename temporary file to new file
        try {
            fs::rename(tmp_file_path, new_file_path);
            
            // Remove original file if different from new file
            if (result.file_path != new_file_path && fs::exists(result.file_path)) {
                if (!fs::equivalent(result.file_path, new_file_path)) {
                    fs::remove(result.file_path);
                }
            }
            
            
            return true;
            
        } catch (const fs::filesystem_error& e) {
            safe_print("Error renaming file %s to %s: %s\n", 
                tmp_file_path.c_str(), new_file_path.c_str(), e.what());
            
            // Clean up temporary file on error
            if (fs::exists(tmp_file_path)) {
                try {
                    fs::remove(tmp_file_path);
                } catch (...) {
                    safe_print("Warning: Could not remove temporary file %s\n", tmp_file_path.c_str());
                }
            }
            
            return false;
        }
        
    } catch (const std::exception& e) {
        safe_print("Error updating file %s: %s\n", result.file_path.c_str(), e.what());
        return false;
    }
}

