// Process a batch of files completely
void process_file_batch_complete(const std::vector<std::string>& file_batch, 
                                bool sort_data, 
                                const std::optional<DbParams>& db_params) {
    std::vector<FileAnalysisResult> successful_results;
    
    // Process each file in the batch
    for (const auto& file_path : file_batch) {
        // Start timing for this file
        auto file_start_time = std::chrono::high_resolution_clock::now();
        
        auto result = analyze_file(file_path, sort_data);
        if (!result) {
            safe_print("skip %s ...\n", file_path.c_str());
            continue;
        }
        
        bool update_success = update_file(*result);
        
        // End timing for this file
        auto file_end_time = std::chrono::high_resolution_clock::now();
        auto file_processing_time = std::chrono::duration_cast<std::chrono::milliseconds>(
            file_end_time - file_start_time);
        
        if (update_success) {
            // Log the processing time
            if (g_logger) {
                std::string filename = fs::path(file_path).filename().string();
                g_logger->log_file_processing(filename, file_processing_time.count(), 
                                           file_start_time, file_end_time);
            }
            
            files_processed++;
            
            // Update progress periodically
            if (files_processed % 100 == 0) {
                update_progress();
            }
        }
    }
    
    // Update database if needed and there are successful results
    if (db_params && !successful_results.empty()) {
        // update_database_batch(successful_results, *db_params);
    }
}

// Find all JSON files matching the expected naming pattern
std::vector<std::string> find_json_files(const std::string& directory) {
    std::vector<std::string> json_files;
    
    try {
        for (const auto& entry : fs::recursive_directory_iterator(directory)) {
            if (entry.is_regular_file()) {
                std::string filename = entry.path().filename().string();
                if (std::regex_match(filename, FILENAME_PATTERN)) {
                    json_files.push_back(entry.path().string());
                }
            }
        }
    } catch (const fs::filesystem_error& e) {
        safe_print("Error searching directory %s: %s\n", directory.c_str(), e.what());
    }
    
    return json_files;
}

// Main function
int main(int argc, char* argv[]) {
    auto start_time = std::chrono::high_resolution_clock::now();
    
    // Setup argument parser
    argparse::ArgumentParser program("crypto_data_processor");
    program.add_description("Update JSON files and optionally update database records in batches.");
    
    // Create mutually exclusive group for input source
    program.add_argument("--files")
        .help("List of specific JSON files to process")
        .nargs(argparse::nargs_pattern::at_least_one)
        .metavar("FILE");
        
    program.add_argument("--dir")
        .help("Directory containing JSON files to process recursively")
        .metavar("DIRECTORY");
    
    program.add_argument("--no-sort")
        .help("Disable sorting of the root.data array by timestamp")
        .default_value(false)
        .implicit_value(true)
        .nargs(0);
    
    program.add_argument("--db-host")
        .help("MySQL database host")
        .default_value(std::string("localhost"))
        .metavar("HOST");
    
    program.add_argument("--db-user")
        .help("MySQL database username")
        .metavar("USER");
    
    program.add_argument("--db-password")
        .help("MySQL database password")
        .metavar("PASSWORD");
    
    program.add_argument("--db-name")
        .help("MySQL database name")
        .metavar("DATABASE");
    
    program.add_argument("--table-name")
        .help("MySQL table name")
        .default_value(std::string("processedfiles"))
        .metavar("TABLE");
    
    program.add_argument("--batch-size")
        .help("Number of files per processing batch")
        .default_value(100)
        .scan<'i', int>()
        .metavar("SIZE");
    
    program.add_argument("--worker-threads")
        .help("Number of worker threads")
        .default_value(static_cast<int>(std::thread::hardware_concurrency()))
        .scan<'i', int>()
        .metavar("THREADS");
        
    program.add_argument("--log-file")
        .help("Path to the processing time log file")
        .default_value(std::string("file_processing_times.csv"))
        .metavar("LOG_FILE");
    
    // Parse arguments
    try {
        program.parse_args(argc, argv);
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        std::cerr << program;
        return 1;
    }
    
    // Check if either --files or --dir is provided
    if (!program.is_used("--files") && !program.is_used("--dir")) {
        std::cerr << "Error: Either --files or --dir must be provided." << std::endl;
        std::cerr << program;
        return 1;
    }
    
    // Get file paths
    std::vector<std::string> file_paths;
    
    if (program.is_used("--dir")) {
        std::string dir = program.get<std::string>("--dir");
        std::cout << "Searching for files recursively in directory: " << dir << std::endl;
        file_paths = find_json_files(dir);
    } else {
        auto files = program.get<std::vector<std::string>>("--files");
        for (const auto& file : files) {
            if (fs::is_regular_file(file)) {
                file_paths.push_back(file);
            }
        }
    }
    
    if (file_paths.empty()) {
        std::cout << "No valid JSON files found or specified to process." << std::endl;
        return 0;
    }
    
    // Shuffle files to distribute large files evenly
    std::random_device rd;
    std::mt19937 g(rd());
    std::shuffle(file_paths.begin(), file_paths.end(), g);
    
    std::cout << "Found " << file_paths.size() << " files to process (randomly shuffled)." << std::endl;
    total_files = file_paths.size();
    
    // Prepare settings
    bool sort_data = !program.get<bool>("--no-sort");
    int batch_size = program.get<int>("--batch-size");
    int num_threads = program.get<int>("--worker-threads");
    
    // Initialize the logger
    std::string log_file_path = program.get<std::string>("--log-file");
    g_logger = std::make_shared<FileLogger>(log_file_path);
    std::cout << "Processing times will be logged to: " << log_file_path << std::endl;
    
    // Check database parameters
    std::optional<DbParams> db_params;
    if (program.is_used("--db-user") && program.is_used("--db-password") && program.is_used("--db-name")) {
        db_params = DbParams{
            .host = program.get<std::string>("--db-host"),
            .user = program.get<std::string>("--db-user"),
            .password = program.get<std::string>("--db-password"),
            .database = program.get<std::string>("--db-name"),
            .table = program.get<std::string>("--table-name")
        };
        std::cout << "Database updates enabled." << std::endl;
    } else {
        std::cout << "Database updates disabled (missing parameters)." << std::endl;
    }
    
    // Divide files into batches
    std::vector<std::vector<std::string>> file_batches;
    for (size_t i = 0; i < file_paths.size(); i += batch_size) {
        std::vector<std::string> batch;
        for (size_t j = i; j < i + batch_size && j < file_paths.size(); ++j) {
            batch.push_back(file_paths[j]);
        }
        file_batches.push_back(std::move(batch));
    }
    
    // Adjust number of threads if necessary
    num_threads = std::min(num_threads, static_cast<int>(file_batches.size()));
    num_threads = std::max(1, num_threads);
    
    std::cout << "Starting processing with " << num_threads << " worker thread(s)..." << std::endl;
    
    // Process batches using multiple threads
    std::vector<std::thread> threads;
    
    if (num_threads > 1) {
        // Distribute batches among threads
        for (int t = 0; t < num_threads; ++t) {
            // Note: g_logger is a global variable, so it's accessible in the thread
            threads.emplace_back([t, num_threads, &file_batches, sort_data, &db_params]() {
                for (size_t i = t; i < file_batches.size(); i += num_threads) {
                    process_file_batch_complete(file_batches[i], sort_data, db_params);
                }
            });
        }
        
        // Wait for all threads to complete
        for (auto& thread : threads) {
            thread.join();
        }
    } else {
        // Single-threaded processing
        for (const auto& batch : file_batches) {
            process_file_batch_complete(batch, sort_data, db_params);
        }
    }
    
    // Final progress update
    update_progress();
    std::cout << std::endl;
    
    // Calculate elapsed time
    auto end_time = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time);
    double total_seconds = duration.count() / 1000.0;
    double avg_time_per_file = total_seconds / files_processed.load();
    
    // Print summary
    std::cout << "\n--- Processing Summary ---" << std::endl;
    std::cout << "  Total files processed: " << files_processed << std::endl;
    std::cout << "  Total database records updated: " << db_records_updated << std::endl;
    std::cout << "  Total processing time: " << std::fixed << std::setprecision(2) << total_seconds << " seconds" << std::endl;
    std::cout << "  Average time per file: " << std::fixed << std::setprecision(4) << avg_time_per_file << " seconds" << std::endl;
    
    return 0;
}
